import{_ as o,a0 as a,w as r,s as m,I as e,x as s,a1 as i,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Debian 上使用 systemd 管理系統 | LCTT x X-CMD","titleTemplate":false,"description":"在 Debian 上使用 systemd 管理系統 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Debian 上使用 systemd 管理系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Debian 上使用 systemd 管理系統 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140711 How to use systemd for system administration on Debian","title":"在 Debian 上使用 systemd 管理系統","tag":"201410","desc":""},"relativePath":"201410/20140711 How to use systemd for system administration on Debian.md","filePath":"[post].md"}'),y={name:"201410/20140711 How to use systemd for system administration on Debian.md"};function p(u,t,b,g,f,T){const l=a("Link");return r(),m("div",null,[t[21]||(t[21]=e("h1",{id:"在-debian-上使用-systemd-管理系統",tabindex:"-1"},[s("在 Debian 上使用 systemd 管理系統 "),e("a",{class:"header-anchor",href:"#在-debian-上使用-systemd-管理系統","aria-label":"Permalink to “在 Debian 上使用 systemd 管理系統”"},"​")],-1)),e("p",null,[t[2]||(t[2]=s("人類已經無法阻止 systemd 佔領全世界的 Linux 系統了，唯一阻止它的方法是在你自己的機器上手動卸載它。到目前為止，systemd 已經創建了比任何軟件都多的技術問題、感情問題和社會問題。這一點從",-1)),i(l,{href:"https://lists.debian.org/debian-devel/2013/10/msg00444.html"},{default:n(()=>[...t[0]||(t[0]=[s("“Linux 初始化軟件之戰”",-1)])]),_:1}),t[3]||(t[3]=s("上就能看出，這場爭論在 Debian 開發者之間持續了好幾個月。當 Debian 技術委員會最終決定將 systemd 放到 Debian 8（代號 Jessie）的發行版裏面時，其反對者試圖通過多種努力來",-1)),i(l,{href:"https://lists.debian.org/debian-devel/2014/02/msg00316.html"},{default:n(()=>[...t[1]||(t[1]=[s("取代這項決議",-1)])]),_:1}),t[4]||(t[4]=s("，甚至有人揚言要威脅那些支持 systemd 的開發者的生命安全。",-1))]),t[22]||(t[22]=d(`<p>這也説明了 systemd 對 Unix 傳承下來的系統處理方式有很大的干擾。“一個軟件只做一件事情”的哲學思想已經被這個新來者徹底顛覆。除了取代了 sysvinit 成為新的系統初始化工具外，systemd 還是一個系統管理工具。目前為止，由於 systemd-sysv 這個軟件包提供的兼容性，那些我們使用慣了的工具還能繼續工作。但是當 Debian 將 systemd 升級到214版本後，這種兼容性就不復存在了。升級措施預計會在 Debian 8 &quot;Jessie&quot; 的穩定分支上進行。從此以後用户必須使用新的命令來管理系統、執行任務、變換運行級別、查詢系統日誌等等。不過這裏有一個應對方案，那就是在 .bashrc 文件裏面添加一些別名。</p><p>現在就讓我們來看看 systemd 是怎麼改變你管理系統的習慣的。在使用 systemd 之前，你得先把 sysvinit 保存起來，以便在 systemd 出錯的時候還能用 sysvinit 啓動系統。這種方法<strong>只有在沒安裝 systemd-sysv 的情況下才能生效</strong>，具體操作方法如下：</p><pre><code># cp -av /sbin/init /sbin/init.sysvinit 
</code></pre><p>在緊急情況下，可以把下面的文本：</p><pre><code>init=/sbin/init.sysvinit
</code></pre><p>添加到內核啓動參數項那裏。</p><h3 id="systemctl-的基本用法" tabindex="-1">systemctl 的基本用法 <a class="header-anchor" href="#systemctl-的基本用法" aria-label="Permalink to “systemctl 的基本用法”">​</a></h3><p>systemctl 的功能是替代“/etc/init.d/foo start/stop”這類命令，另外，其實它還能做其他的事情，這點你可以參考 man 文檔。</p><p>一些基本用法：</p><ul><li>systemctl - 列出所有單元（UNIT）以及它們的狀態（這裏的 UNIT 指的就是系統上的 job 和 service）</li><li>systemctl list-units - 列出所有 UNIT</li><li>systemctl start [NAME...] - 啓動一項或多項 UNIT</li><li>systemctl stop [NAME...] - 停止一項或多項 UNIT</li><li>systemctl disable [NAME...] - 將 UNIT 設置為開機不啓動</li><li>systemctl list-unit-files - 列出所有已安裝的 UNIT，以及它們的狀態</li><li>systemctl --failed - 列出開機啓動失敗的 UNIT</li><li>systemctl --type=mount - 列出某種類型的 UNIT，類型包含：service, mount, device, socket, target</li><li>systemctl enable debug-shell.service - 將一個 shell 腳本設置為開機啓動，用於調試</li></ul><p>為了更方便處理這些 UNIT，你可以使用 systemd-ui 軟件包，你只要輸入 systemadm 命令就可以使用這個軟件。</p><p>你同樣可以使用 systemctl 實現轉換運行級別、重啓系統和關閉系統的功能：</p><ul><li>systemctl isolate graphical.target - 切換到運行級別5，就是有桌面的運行級別</li><li>systemctl isolate multi-user.target - 切換到運行級別3，沒有桌面的運行級別</li><li>systemctl reboot - 重啓系統</li><li>systemctl poweroff - 關機</li></ul><p>所有命令，包括切換到其他運行級別的命令，都可以在普通用户的權限下執行。</p><h3 id="journalctl-的基本用法" tabindex="-1">journalctl 的基本用法 <a class="header-anchor" href="#journalctl-的基本用法" aria-label="Permalink to “journalctl 的基本用法”">​</a></h3><p>systemd 不僅提供了比 sysvinit 更快的啓動速度，還讓日誌系統在更早的時候啓動起來，可以記錄內核初始化階段、內存初始化階段、前期啓動步驟以及主要的系統執行過程的日誌。所以，<strong>以前那種需要通過對顯示屏拍照或者暫停系統來調試程序的日子已經一去不復返啦</strong>。</p><p>systemd 的日誌文件都被放在 /var/log 目錄。如果你想使用它的日誌功能，需要執行一些命令，因為 Debian 沒有打開日誌功能。命令如下：</p><pre><code># addgroup --system systemd-journal
# mkdir -p /var/log/journal
# chown root:systemd-journal /var/log/journal
# gpasswd -a $user systemd-journal 
</code></pre><p>通過上面的設置，你就可以以普通用户權限使用 journal 軟件查看日誌。使用 journalctl 查詢日誌可以獲得一些比 syslog 軟件更方便的玩法：</p><ul><li>journalctl --all - 顯示系統上所有日誌，以及它的用户</li><li>journalctl -f - 監視系統日誌的變化（類似 tail -f /var/log/messages 的效果）</li><li>journalctl -b - 顯示系統啓動以後的日誌</li><li>journalctl -k -b -1 - 顯示上一次（-b -1）系統啓動前產生的內核日誌</li><li>journalctl -b -p err - 顯示系統啓動後產生的“ERROR”日誌</li><li>journalctl --since=yesterday - 當系統不會經常重啓的時候，這條命令能提供比 -b 更短的日誌記錄</li><li>journalctl -u cron.service --since=&#39;2014-07-06 07:00&#39; --until=&#39;2014-07-06 08:23&#39; - 顯示 cron 服務在某個時間段內打印出來的日誌</li><li>journalctl -p 2 --since=today - 顯示優先級別為2以內的日誌，包含 emerg、alert、crit三個級別。所有日誌級別有： emerg (0), alert (1), crit (2), err (3), warning (4), notice (5), info (6), debug (7)</li><li>journalctl &gt; yourlog.log - 將二進制日誌文件複製成文本文件並保存到當前目錄</li></ul><p>Journal 和 syslog 可以很好的共存。而另一方面，一旦你習慣了操作 journal，你也可以卸載掉所有 syslog 的軟件，比如 rsyslog 或 syslog-ng。</p><p>如果想要得到更詳細的日誌信息，你可以在內核啓動參數上添加“systemd.log_level=debug”，然後運行下面的命令：</p><pre><code># journalctl -alb 
</code></pre><p>你也可以編輯 /etc/systemd/system.conf 文件來修改日誌級別。</p><h3 id="利用-systemd-分析系統啓動過程" tabindex="-1">利用 systemd 分析系統啓動過程 <a class="header-anchor" href="#利用-systemd-分析系統啓動過程" aria-label="Permalink to “利用 systemd 分析系統啓動過程”">​</a></h3><p>systemd 可以讓你能更有效地分析和優化你的系統啓動過程：</p><ul><li>systemd-analyze - 顯示本次啓動系統過程中用户態和內核態所花的時間</li><li>systemd-analyze blame - 顯示每個啓動項所花費的時間明細</li><li>systemd-analyze critical-chain - 按時間順序打印 UNIT 樹</li><li>systemd-analyze dot | dot -Tsvg &gt; systemd.svg - 為開機啓動過程生成向量圖（需要安裝 graphviz 軟件包）</li><li>systemd-analyze plot &gt; bootplot.svg - 產生開機啓動過程的時間圖表</li></ul><p><img src="https://farm6.staticflickr.com/5559/14607588994_38543638b3_z.jpg" alt=""></p><p><img src="https://farm6.staticflickr.com/5565/14423020978_14b21402c8_z.jpg" alt=""></p>`,29)),e("p",null,[t[7]||(t[7]=s("systemd 雖然是個年輕的項目，但已有大量文檔。首先要介紹給你的是",-1)),i(l,{href:"http://0pointer.de/blog/projects/systemd.html"},{default:n(()=>[...t[5]||(t[5]=[s("Lennart Poettering 的 0pointer 系列",-1)])]),_:1}),t[8]||(t[8]=s("。這個系列非常詳細，非常有技術含量。另外一個是",-1)),i(l,{href:"http://www.freedesktop.org/wiki/Software/systemd/"},{default:n(()=>[...t[6]||(t[6]=[s("免費桌面信息文檔",-1)])]),_:1}),t[9]||(t[9]=s("，它包含了最詳細的關於 systemd 的鏈接：發行版特性文件、bug 跟蹤系統和説明文檔。你可以使用下面的命令來查詢 systemd 都提供了哪些文檔：",-1))]),t[23]||(t[23]=e("pre",null,[e("code",null,`# man systemd.index 
`)],-1)),t[24]||(t[24]=e("p",null,"不同發行版之間的 systemd 提供的命令基本一樣，最大的不同之處就是打包方式。",-1)),t[25]||(t[25]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=s("via: ",-1)),i(l,{href:"http://xmodulo.com/2014/07/use-systemd-system-administration-debian.html"},{default:n(()=>[...t[10]||(t[10]=[s("http://xmodulo.com/2014/07/use-systemd-system-administration-debian.html",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=s("譯者：",-1)),i(l,{href:"https://github.com/bazz2"},{default:n(()=>[...t[12]||(t[12]=[s("bazz2",-1)])]),_:1}),t[15]||(t[15]=s(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=s("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[16]||(t[16]=[s("LCTT",-1)])]),_:1}),t[19]||(t[19]=s(" 原創翻譯，",-1)),i(l,{href:"http://linux.cn/"},{default:n(()=>[...t[17]||(t[17]=[s("Linux中國",-1)])]),_:1}),t[20]||(t[20]=s(" 榮譽推出",-1))])])}const D=o(y,[["render",p]]);export{x as __pageData,D as default};
